	private static final class PathSource implements NativeLmdbQuerySource.ParallelSource {
		static final long A = 1_000L;
		final AtomicInteger opened;
		final AtomicInteger closed;
		final AtomicInteger terminalVisits;
		final Object identity;
		final List<long[]> triples;

		PathSource() {
			opened = new AtomicInteger();
			closed = new AtomicInteger();
			terminalVisits = new AtomicInteger();
			identity = this;
			triples = new ArrayList<>();
			for (long s = 1; s <= 4; s++) {
				for (long branch = 0; branch < 2; branch++) {
					long x = 100L + 2L * s + branch;
					triples.add(new long[] { s, 1L, x, 0L });
					triples.add(new long[] { x, 2L, A, 0L });
				}
			}
		}

		PathSource(PathSource owner) {
			opened = owner.opened;
			closed = owner.closed;
			terminalVisits = owner.terminalVisits;
			identity = owner.identity;
			triples = owner.triples;
		}

		@Override
		public ParallelSource[] openParallelSources(int count) {
			opened.addAndGet(count);
			ParallelSource[] workers = new ParallelSource[count];
			for (int i = 0; i < count; i++) {
				workers[i] = new PathSource(this);
			}
			return workers;
		}

		@Override
		public NativeProbe newProbe() {
			return new NativeProbe() {
				@Override
				public RecordIterator open(long subj, long pred, long obj, long context) {
					return statements(subj, pred, obj, context);
				}

				@Override
				public NativeAdjacency adjacency(long predicate, boolean bySubject) {
					if (predicate != 1L && predicate != 2L) {
						return null;
					}
					Map<Long, List<Long>> runs = new TreeMap<>();
					for (long[] triple : triples) {
						if (triple[1] == predicate) {
							runs.computeIfAbsent(triple[bySubject ? 0 : 2], ignored -> new ArrayList<>())
									.add(triple[bySubject ? 2 : 0]);
						}
					}
					List<Long> keys = new ArrayList<>(runs.keySet());
					return new NativeAdjacency() {
						@Override
						public long find(long key) {
							int index = keys.indexOf(key);
							return index < 0 ? NOT_FOUND : index + 1L;
						}

						@Override
						public long size(long handle) {
							return runs.get(keys.get((int) handle - 1)).size();
						}

						@Override
						public long neighborAt(long handle, long offset) {
							if (predicate == 2L && bySubject) {
								terminalVisits.incrementAndGet();
							}
							return runs.get(keys.get((int) handle - 1)).get((int) offset);
						}

						@Override
						public long contextAt(long handle, long offset) {
							return 0L;
						}

						@Override
						public boolean runsNeighborOrdered() {
							return true;
						}

						@Override
						public boolean supportsKeyEnumeration() {
							return true;
						}

						@Override
						public long keyCount() {
							return keys.size();
						}

						@Override
						public long keyAt(long ordinal) {
							return keys.get((int) ordinal);
						}
					};
				}

				@Override
				public void close() {
				}
			};
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return predicate == 1L ? OptionalLong.of(bySubject ? 4L : 8L)
					: predicate == 2L ? OptionalLong.of(bySubject ? 8L : 1L) : OptionalLong.empty();
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			OptionalLong keys = adjacencyKeyDomainCardinality(predicate, bySubject);
			return keys.isPresent() ? OptionalDouble.of(keys.getAsLong()) : OptionalDouble.empty();
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			OptionalLong keys = adjacencyKeyDomainCardinality(predicate, bySubject);
			return keys.isPresent() ? OptionalDouble.of(8D / keys.getAsLong()) : OptionalDouble.empty();
		}

		@Override
		public Object idSpace() {
			return identity;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public long idOf(Value value) {
			return UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return SimpleValueFactory.getInstance().createIRI("urn:duplicate-path:" + id);
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			List<long[]> matches = triples.stream()
					.filter(triple -> (subj == UNKNOWN_ID || subj == triple[0])
							&& (pred == UNKNOWN_ID || pred == triple[1]) && (obj == UNKNOWN_ID || obj == triple[2])
							&& (context == UNKNOWN_ID || context == triple[3]))
					.toList();
			return new RecordIterator() {
				int index;

				@Override
				public long[] next() {
					return index < matches.size() ? matches.get(index++) : null;
				}

				@Override
				public void close() {
				}
			};
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			long count = 0L;
			try (RecordIterator records = statements(subj, pred, obj, context)) {
				while (records.next() != null) {
					count++;
				}
			}
			return count;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			return count(subj, pred, obj, context) > 0L;
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return count(subj, pred, obj, context);
		}

		@Override
		public void close() {
			closed.incrementAndGet();
		}
	}
